  const first = items.find(i => i.op === 'put');
  if (!first) { await clearQueue(); return { committed: 0, conflicts: [] }; }

  const res = await ok(await rest(`/repos/${c.owner}/${c.repo}/contents/${encodeURI(first.path)}`, {
    config: c, method: 'PUT',
